MS.hook('resource:keep', function (kind, url) {
  if (kind !== 'video') return true;
  var exts = MS.config.get('exts', ['.mp4', '.webm', '.mkv', '.mov', '.m4v', '.flv']);
  if (!exts || !exts.length) return true;
  var u = String(url || '').toLowerCase().split('#')[0].split('?')[0];
  var m = u.match(/\.([a-z0-9]{2,5})$/);
  if (!m) return true;
  var hit = '.' + m[1];
  for (var i = 0; i < exts.length; i++) {
    if (String(exts[i] || '').toLowerCase() === hit) return true;
  }
  var KNOWN = ['.mp4', '.webm', '.mkv', '.mov', '.m4v', '.flv', '.avi', '.wmv',
               '.ts', '.m3u8', '.mpd', '.3gp', '.ogv', '.rmvb', '.f4v'];
  if (KNOWN.indexOf(hit) >= 0) return false;
  return true;
});

var accepted = Object.create(null);
var acceptedSize = 0;
function normKey(u) {
  try {
    var a = new URL(u, location.href);
    return a.origin + a.pathname;
  } catch (e) {
    return String(u).split('#')[0].split('?')[0];
  }
}
MS.hook('resource:keep', function (kind, url) {
  var u = String(url || '');
  if (!u) return true;
  var key = normKey(u);
  var prev = accepted[key];
  if (!prev) {
    if (acceptedSize > 8000) { accepted = Object.create(null); acceptedSize = 0; }
    accepted[key] = u;
    acceptedSize++;
    return true;
  }
  return prev === u;
});

MS.hook('resource:keep', function (kind, url, meta) {
  if (kind !== 'img') return true;
  var junk = /(pixel|spacer|blank|transparent|1x1|loading|placeholder|clear\.gif|spacer\.gif)/i;
  if (junk.test(String(url || ''))) return false;
  var minBytes = MS.config.get('minBytes', 8192);
  var minW = MS.config.get('minWidth', 100);
  var minH = MS.config.get('minHeight', 100);
  if (meta) {
    if (meta.size > 0 && minBytes > 0 && meta.size < minBytes) return false;
    if (meta.width > 0 && minW > 0 && meta.width < minW) return false;
    if (meta.height > 0 && minH > 0 && meta.height < minH) return false;
  }
  return true;
});

MS.hook('resource:keep', function (kind, url) {
  var hosts = MS.config.get('hosts', []);
  if (!hosts || !hosts.length) return true;
  var h = '';
  try {
    h = new URL(String(url), location.href).hostname.toLowerCase();
  } catch (e) {
    return true;
  }
  for (var i = 0; i < hosts.length; i++) {
    var d = String(hosts[i] || '').toLowerCase().trim().replace(/^\.+/, '');
    if (!d) continue;
    if (h === d) return false;
    if (h.length > d.length && h.slice(-(d.length + 1)) === '.' + d) return false;
  }
  return true;
});

MS.hook('download:filename', function (name, url, idx) {
  var sep = MS.config.get('sep', '_');
  var host = '';
  try {
    host = new URL(String(url), location.href).hostname.replace(/^www\./, '');
  } catch (e) {
    return name;
  }
  if (!host) return name;
  if (String(name).indexOf(host + sep) === 0) return name;
  return host + sep + name;
});

MS.hook('download:filename', function (name, url, idx) {
  var pad = MS.config.get('pad', 3);
  var sep = MS.config.get('sep', '_');
  var n = String(idx || 0);
  while (n.length < pad) n = '0' + n;
  if (String(name).indexOf(n + sep) === 0) return name;
  return n + sep + name;
});

MS.hook('download:quality', function (pref) {
  var q = MS.config.get('quality', 'high');
  if (q === 'high' || q === 'medium' || q === 'low') return q;
  return pref;
});

MS.hook('render:layout', function (cur, kind) {
  var w = MS.config.get('minCardWidth', 96);
  w = parseInt(w, 10);
  if (!w || w < 60 || w > 320) return cur;
  return { minCardWidth: w };
});

function copyText(t) {
  try { if (MS.copy) { MS.copy(t); return; } } catch (e0) {}
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(t);
      return;
    }
  } catch (e1) {}
  try {
    var ta = document.createElement('textarea');
    ta.value = t;
    ta.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0;';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    ta.remove();
    return;
  } catch (e2) {}
  MS.log(t);
}
MS.hook('render:footerButtons', function (kind, list) {
  return [{
    label: '复制文件名',
    icon: '📋',
    onClick: function () {
      var arr = MS.media.list(kind) || [];
      if (!arr.length) { MS.toast('当前列表为空', 'warn'); return; }
      var names = [];
      for (var i = 0; i < arr.length; i++) {
        var u = String(arr[i]).split('#')[0].split('?')[0];
        var n = u.split('/').pop();
        names.push(n || u);
      }
      var text = names.join('\n');
      copyText(text);
      MS.toast('已复制 ' + names.length + ' 个文件名', 'success');
    }
  }];
});

MS.hook('theme:colors', function (colors) {
  try {
    var c = colors || {};
    var bg = String(c.bg || '').trim();
    var lum = 1;
    if (/^#[0-9a-f]{3}$/i.test(bg)) {
      bg = '#' + bg.charAt(1) + bg.charAt(1) + bg.charAt(2) + bg.charAt(2) + bg.charAt(3) + bg.charAt(3);
    }
    if (/^#[0-9a-f]{6}$/i.test(bg)) {
      var r = parseInt(bg.slice(1, 3), 16);
      var g = parseInt(bg.slice(3, 5), 16);
      var b = parseInt(bg.slice(5, 7), 16);
      lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
    } else if (/^rgba?\(/i.test(bg)) {
      var mm = bg.match(/(\d+)[,\s]+(\d+)[,\s]+(\d+)/);
      if (mm) lum = (0.299 * +mm[1] + 0.587 * +mm[2] + 0.114 * +mm[3]) / 255;
    }
    if (lum > 0.5) return colors;
    return {
      bg: '#05070d',
      bg2: '#0b1220',
      bg3: '#141c2b',
      txt: '#e8eefc',
      sub: '#93a4c0',
      border: '#1f2a3d',
      primary: c.primary,
      primary2: c.primary2,
      success: c.success,
      warn: c.warn,
      danger: c.danger
    };
  } catch (e) {
    return colors;
  }
});

