MS.hook('shortcuts', function () {
  var mod = MS.config.get('mod', 'alt');
  var key = MS.config.get('key', 'e');
  return [{
    mod: mod,
    key: key,
    run: function () {
      var arr = MS.media.list('img').concat(MS.media.list('video') || []);
      if (!arr.length) { MS.toast('还没有资源', 'warn'); return; }
      var text = arr.join('\n');
      copyText(text);
      MS.toast('已复制 ' + arr.length + ' 条链接', 'success');
    }
  }];
});

MS.hook('parse:result', function (result) {
  if (!result) return result;
  var pat = MS.config.get('pattern', 'watermark|logo|_wm|wm_|/wm/');
  if (!pat) return result;
  var re;
  try {
    re = new RegExp(pat, 'i');
  } catch (e) {
    return result;
  }
  try {
    if (result.videoUrls && result.videoUrls.length > 1) {
      var clean = [];
      for (var i = 0; i < result.videoUrls.length; i++) {
        if (!re.test(String(result.videoUrls[i]))) clean.push(result.videoUrls[i]);
      }
      if (clean.length && clean.length < result.videoUrls.length) {
        result.videoUrls = clean;
        result.videoUrl = clean[0];
      }
    }
  } catch (e2) {}
  return result;
});
